package com.mysterymango.game;

import java.util.*;
import static com.mysterymango.game.Definitions.*;

/** 논리 역할의 상태 저장 어댑터. 행동과 조건 계산은 실제 게임의 MysteryEngine을 공유한다. */
public final class MysterySandboxEngine {
    public Map<String,Object> initial(Map<String,Object> d){var s=obj("phaseIndex",0,"status","ACTIVE","grants",new LinkedHashMap<String,Object>(),"publicClues",new ArrayList<String>(),"investigations",new LinkedHashMap<String,Object>(),"votes",new LinkedHashMap<String,Object>(),"ready",new ArrayList<String>(),"flags",new LinkedHashMap<String,Object>(),"materials",new ArrayList<Map<String,Object>>(),"executions",new ArrayList<String>(),"culpritIdentified",false,"endingId",null);open(d,s,0);return s;}
    public void command(Map<String,Object> d,Map<String,Object> s,int seat,String type,Map<String,Object> p){
        MysteryEngine.require(str(s,"status").equals("ACTIVE"),409,"GAME_FINISHED","종료된 시험입니다.");var role=roleAt(d,seat);String rid=str(role,"id");var phase=phase(d,s);
        switch(type){
            case "ADVANCE_TIME" -> advance(d,s);
            case "PHASE_READY" -> {MysteryEngine.require(str(phase,"kind").equals("READING"),409,"NOT_READING","읽기 단계에서 사용할 수 있습니다.");var ready=new ArrayList<>(strings(s.get("ready")));if(!ready.contains(rid))ready.add(rid);s.put("ready",ready);if(ready.size()==objects(d.get("roles")).size())advance(d,s);}
            case "INVESTIGATE" -> {MysteryEngine.action(phase,"INVESTIGATE");var target=find(d,"targets",str(p,"targetId"));var investigated=new LinkedHashMap<>(map(map(s.get("investigations")).get(rid)));if(investigated.containsKey(str(target,"id")))return;MysteryEngine.investigation(target,str(phase,"id"),remaining(d,s,rid));investigated.put(str(target,"id"),integer(s,"phaseIndex",0));mutable(s,"investigations").put(rid,investigated);for(String clue:strings(target.get("clueIds")))grant(s,rid,clue,true);}
            case "SHARE" -> {MysteryEngine.action(phase,"SHARE");String cid=str(p,"clueId"),scope=str(p,"scope");var clue=find(d,"clues",cid);MysteryEngine.share(clue,Boolean.TRUE.equals(map(map(s.get("grants")).get(rid)).get(cid)),scope);if(scope.equals("PUBLIC")){var pub=new ArrayList<>(strings(s.get("publicClues")));if(!pub.contains(cid)){pub.add(cid);s.put("publicClues",pub);rules(d,s,"CLUE_PUBLISHED",cid,"clue:"+cid);}}else {int to=integer(p,"toSeat",-1);MysteryEngine.require(to!=seat,422,"WHISPER_RECIPIENT_INVALID","다른 역할을 선택해 주세요.");grant(s,str(roleAt(d,to),"id"),cid,false);}}
            case "VOTE" -> {MysteryEngine.action(phase,"VOTE");var votes=mutable(s,"votes");String selected=p.get("roleId")==null?null:str(p,"roleId");MysteryEngine.vote(d,selected,votes.containsKey(rid),(String)votes.get(rid));votes.put(rid,selected);}
            default -> throw BoardEngine.error("INVALID_COMMAND","지원하지 않는 시험 행동입니다.");
        }
    }
    public Map<String,Object> project(Map<String,Object> d,Map<String,Object> s,int seat){
        var role=roleAt(d,seat);String rid=str(role,"id");var p=phase(d,s);var grants=new LinkedHashMap<String,Boolean>();map(map(s.get("grants")).get(rid)).forEach((k,v)->grants.put(k,Boolean.TRUE.equals(v)));Set<String> pub=new HashSet<>(strings(s.get("publicClues")));
        Object ending=null;if(s.get("endingId")!=null){var e=find(d,"endings",str(s,"endingId"));ending=obj("title",e.get("title"),"text",e.get("text"),"objectiveAchieved",RuleConditions.evaluate(map(map(role.get("objective")).get("condition")),facts(d,s,rid)));}
        var votes=map(s.get("votes"));Object ballot=null;if(str(p,"kind").equals("VOTE")){var b=map(d.get("ballot"));ballot=obj("allowChange",b.get("allowChange"),"allowAbstain",b.get("allowAbstain"),"myVote",votes.get(rid),"submitted",votes.containsKey(rid));}
        return obj("status",s.get("status"),"phaseIndex",s.get("phaseIndex"),"phase",obj("definitionId",p.get("id"),"kind",p.get("kind"),"publicText",p.get("publicText"),"actions",p.get("actions"),"ready",strings(s.get("ready")).contains(rid)),"myRole",MysteryEngine.role(d,rid),"participants",objects(d.get("roles")).stream().map(r->obj("roleId",r.get("id"),"roleName",r.get("name"))).toList(),"clues",MysteryEngine.clues(d,grants,pub),"targets",objects(d.get("targets")).stream().filter(t->strings(t.get("phaseIds")).contains(str(p,"id"))).map(t->obj("id",t.get("id"),"name",t.get("name"),"investigated",map(map(s.get("investigations")).get(rid)).containsKey(str(t,"id")))).toList(),"investigationsRemaining",remaining(d,s,rid),"ballot",ballot,"materials",s.get("materials"),"ending",ending);
    }
    private void advance(Map<String,Object> d,Map<String,Object> s){var p=phase(d,s);if(str(p,"kind").equals("VOTE")){String accused=RuleConditions.accusation(map(s.get("votes")).values().stream().map(v->(String)v).toList());s.put("accusedRoleId",accused);s.put("culpritIdentified",Objects.equals(accused,str(map(d.get("ballot")),"culpritRoleId")));rules(d,s,"BALLOT_CLOSED","","ballot:"+integer(s,"phaseIndex",0));}int next=integer(s,"phaseIndex",0)+1;if(next>=objects(d.get("phases")).size())s.put("status","COMPLETED");else open(d,s,next);}
    private void open(Map<String,Object> d,Map<String,Object> s,int n){s.put("phaseIndex",n);s.put("ready",new ArrayList<String>());var p=phase(d,s);rules(d,s,"PHASE_STARTED",str(p,"id"),"phase:"+n);if(str(p,"kind").equals("ENDING"))s.put("endingId",MysteryEngine.ending(d,facts(d,s,"" )).get("id"));}
    private void rules(Map<String,Object> d,Map<String,Object> s,String event,String ref,String cause){MysteryEngine.rules(d,event,ref,cause,()->facts(d,s,""),(rule,why)->{var executed=new ArrayList<>(strings(s.get("executions")));String key=rule+":"+why;if(executed.contains(key))return false;executed.add(key);s.put("executions",executed);return true;},effect->{switch(str(effect,"type")){case "GRANT_CLUE"->grant(s,str(effect,"roleId"),str(effect,"clueId"),true);case "PUBLISH_MATERIAL"->{var materials=new ArrayList<>(objects(s.get("materials")));materials.add(obj("id",UUID.randomUUID().toString(),"text",effect.get("text")));s.put("materials",materials);}case "SET_FLAG"->mutable(s,"flags").put(str(effect,"flag"),effect.get("value"));default->throw BoardEngine.error("INVALID_RULE","지원하지 않는 규칙입니다.");}});}
    private static RuleConditions.Facts facts(Map<String,Object> d,Map<String,Object> s,String role){Set<String> pub=new HashSet<>(strings(s.get("publicClues")));var roles=new LinkedHashMap<String,Set<String>>();for(var r:objects(d.get("roles"))){var clues=new HashSet<>(pub);clues.addAll(map(map(s.get("grants")).get(str(r,"id"))).keySet());roles.put(str(r,"id"),clues);}return new RuleConditions.Facts(bool(s,"culpritIdentified"),pub,roles,map(s.get("flags")),role);}
    private static void grant(Map<String,Object> s,String rid,String cid,boolean owned){var g=new LinkedHashMap<>(map(map(s.get("grants")).get(rid)));g.put(cid,Boolean.TRUE.equals(g.get(cid))||owned);mutable(s,"grants").put(rid,g);}
    private static Map<String,Object> mutable(Map<String,Object> s,String key){var value=new LinkedHashMap<>(map(s.get(key)));s.put(key,value);return value;}
    public static Map<String,Object> phase(Map<String,Object> d,Map<String,Object> s){return objects(d.get("phases")).get(integer(s,"phaseIndex",0));}
    private static Map<String,Object> roleAt(Map<String,Object> d,int seat){var roles=objects(d.get("roles"));MysteryEngine.require(seat>=0&&seat<roles.size(),422,"INVALID_SEAT","역할을 선택해 주세요.");return roles.get(seat);}
    private static int remaining(Map<String,Object> d,Map<String,Object> s,String rid){long used=map(map(s.get("investigations")).get(rid)).values().stream().filter(v->v instanceof Number n&&n.intValue()==integer(s,"phaseIndex",0)).count();return Math.max(0,integer(phase(d,s),"investigationLimit",0)-(int)used);}
}
